insert into public.site_settings (id, data) values (1, '{"name":"M R Sharier Kabir","shortName":"Sharier","initials":"MRSK","role":"Full-Stack Developer","headline":"I build products people","headlineAccent":"actually use.","pitch":"CSE student at AIUB and full-stack developer from Dhaka. I design, build and ship web and mobile apps end-to-end — from the database schema to the last animation frame.","availability":"Open to internships, junior roles & freelance","available":true,"location":"Dhaka, Bangladesh","timezone":"Asia/Dhaka","email":"sharier48@gmail.com","phone":"+880 1722-550023","showPhone":true,"github":"https://github.com/mrsharierkabir","linkedin":"https://www.linkedin.com/in/m-r-sharier-kabir/","socials":[{"label":"GitHub","url":"https://github.com/mrsharierkabir"},{"label":"LinkedIn","url":"https://www.linkedin.com/in/m-r-sharier-kabir/"}],"avatarUrl":"","resumeUrl":"/resume/M-R-Sharier-Kabir-Resume.pdf","bio":["I''m Sharier — a Computer Science & Engineering student at American International University-Bangladesh and a full-stack developer who likes owning a product from the first sketch to the live URL.","I''ve shipped a live e-commerce store for a client, built a WhatsApp-style messaging app, and made a handful of tools I use every day — an expiry tracker, a personal finance app and a web scraper. I care about clean data models, fast interfaces and details that make software feel considered.","Right now I''m looking for an internship or junior role where I can learn from a strong team and ship real things."],"facts":[{"label":"Based in","value":"Dhaka, Bangladesh (GMT+6)"},{"label":"Studying","value":"BSc in CSE · AIUB"},{"label":"Focus","value":"Full-stack web · Mobile · Databases"},{"label":"Status","value":"Available for work"}],"hobbies":["Building side projects","Designing UI","Reading tech blogs","Gaming","Watching films"],"likes":["Clean, well-named code","Thoughtful animation","Solving real problems","Good coffee at the desk"],"dislikes":["Unclear requirements","Bloated UIs","Skipping the data model","Slow websites"],"languages":["Bangla (native)","English (professional)"],"lookingFor":"Internships, junior full-stack roles and freelance builds.","marquee":["Full-Stack Developer","React & Next.js","Supabase & Postgres","Flutter","Python","UI Engineering","Available for work"],"seoDescription":"M R Sharier Kabir — full-stack developer and CSE student in Dhaka. Web and mobile products built end-to-end with React, Next.js, Supabase, Flutter and Python.","contactIntro":"Have a role, a project or a question? Send a message — I usually reply within a day."}'::jsonb)
insert into public.projects (id, sort, published, featured, slug, title, category, device, summary, description, role, year, country, client, stack, features, live_url, repo_url, cover_url, gallery, accent) values
  ('00000000-0000-4000-8000-100000000001', 1, true, true, 'shohoz-bazar', 'Shohoz Bazar', 'E-commerce · Client project', 'web', 'A live online store for a Bangladeshi retail client — catalogue, cart and checkout, built and launched by me end-to-end.', 'Shohoz Bazar needed to move its business online with a store customers could trust and the owner could manage without a developer. I handled the whole build: product and category structure, the storefront, cart and checkout flow, order handling, and deployment to shohazbazar.com.
